alter table public.applications add column if not exists payment_status text not null default 'Pending', add column if not exists payment_proof jsonb;
alter table public.applications drop constraint if exists applications_payment_status_check;
alter table public.applications add constraint applications_payment_status_check check (payment_status in ('Pending','Submitted','Confirmed','Rejected','Not Required'));
drop function if exists public.track_application(text,text);
create function public.track_application(p_reference text,p_phone text) returns table(reference text,full_name text,service text,status text,created_at timestamptz,deletion_reason text,quoted_amount numeric,payment_status text) language sql security definer set search_path=public as $$ select a.reference,a.full_name,a.service,a.status,a.created_at,a.deletion_reason,a.quoted_amount,a.payment_status from public.applications a where upper(a.reference)=upper(trim(p_reference)) and regexp_replace(a.phone,'[^0-9]','','g')=regexp_replace(trim(p_phone),'[^0-9]','','g') limit 1; $$;
revoke all on function public.track_application(text,text) from public; grant execute on function public.track_application(text,text) to anon,authenticated;
create or replace function public.submit_payment_proof(p_reference text,p_phone text,p_path text,p_name text,p_type text,p_size bigint) returns boolean language plpgsql security definer set search_path=public as $$ declare target_id uuid; begin select id into target_id from public.applications where upper(reference)=upper(trim(p_reference)) and regexp_replace(phone,'[^0-9]','','g')=regexp_replace(trim(p_phone),'[^0-9]','','g') and status<>'Deleted' limit 1; if target_id is null then raise exception 'Application not found.'; end if; update public.applications set payment_proof=jsonb_build_object('path',p_path,'name',p_name,'type',p_type,'size',p_size),payment_status='Submitted' where id=target_id; return true; end; $$;
revoke all on function public.submit_payment_proof(text,text,text,text,text,bigint) from public; grant execute on function public.submit_payment_proof(text,text,text,text,text,bigint) to anon,authenticated;
